import{z as r,x as s,o as e,c as B,q as i,j as l,D as E,d as o,s as n,S as p}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"新凯恩斯粘性价格","description":"","frontmatter":{"title":"新凯恩斯粘性价格","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/new-keynesian.md","filePath":"econ/new-keynesian.md","lastUpdated":1791063341000}'),d={name:"econ/new-keynesian.md"};function A(h,a,_,C,m,D){const t=s("Mermaid");return e(),B("div",null,[a[2]||(a[2]=i('<h1 id="新凯恩斯粘性价格" tabindex="-1">新凯恩斯粘性价格 <a class="header-anchor" href="#新凯恩斯粘性价格" aria-label="Permalink to &quot;新凯恩斯粘性价格&quot;">​</a></h1><div class="epigraph"><p>名义利率能暂时支配实际利率，是因为价格不能立刻把所有商品的标价改完；前瞻的菲利普斯把通胀接到预期与缺口。</p><footer>—— Woodford, Interest and Prices, 2003；对照 Calvo 交错定价</footer></div><p><a href="/econ/hall-random-walk">上一课</a>（Hall 随机游走）。用欧拉替换了 \\(C(Y)\\)。若价格完全灵活，欧拉里的实际利率由实物出清决定，名义利率只是费雪意义上的加层——回到货币中性。本课的缺口是：在垄断竞争与交错调价下，名义政策利率能在一段时间内移动 \\(i-\\mathbb{E}\\pi\\)，从而沿欧拉移动需求。Woodford 把这套装置写成利息规则下的新凯恩斯综合；RBC 对照是下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Hicks 的 LM 靠外生 \\(M\\) 与给定 \\(P\\) 出 \\(i\\)。现代央行钉的是隔夜利率，准备金往往充足。缺口不是再画 LM，而是：为何 \\(i\\) 不是马上被 \\(P\\) 的跳跃中和。Calvo 型厂商每期只有一部分能改名义价格，未改价的相对价格被通胀稀释。加成与边际成本的缺口使通胀满足前瞻菲利普斯</p> \\[\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\kappa\\tilde{y}_t, \\]<p>\\(\\tilde{y}\\) 为产出对自然率产出的偏离（自然率产出是灵活价格下的产出，可随真实冲击动）。与 Friedman–Phelps 的差别是：\\(\\pi^e\\) 明确等于 \\(\\mathbb{E}_t\\pi_{t+1}\\)，并且来自优化的调价，不是外贴的适应性。</p><p><span class="marginnote">Calvo 交错定价可以读成「抽签改价」：每期每个厂商抽签，只有中签的那部分（比例 \\(1-\\theta\\)）才被允许改标价，其余的只能眼看通胀稀释自己的相对价格。\\(\\theta\\) 越大，中签率越低，价格越粘，\\(\\kappa\\) 越小。</span></p><p><span class="marginnote">自然产出不是索洛稳态本身：它可以因技术、markup 冲击而波动。货币仍然长期中性：稳态通胀由名义锚决定，\\(\\tilde{y}=0\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三块：欧拉（动态 IS）、新凯恩斯菲利普斯、政策利率规则（泰勒规则是后课，本课可先把 \\(i\\) 当成外生路径）。Woodford（2003）强调均衡是利率路径与预期系统的解，不必先指定 \\(M\\)。数量方程在后台：一旦 \\(i\\) 与 \\(P\\) 定了，货币需求给出 \\(M\\)，操作上由央行按需供给。</p>',11)),(e(),l(p,null,{default:E(()=>[n(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%AC%A7%E6%8B%89%20%2F%20%E5%8A%A8%E6%80%81%20IS%22%5D%20--%3E%20YGAP%5B%22%E7%BC%BA%E5%8F%A3%20y%CC%83%22%5D%0A%20%20STICK%5B%22%E4%BA%A4%E9%94%99%E5%90%8D%E4%B9%89%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20NKPC%5B%22%E5%89%8D%E7%9E%BB%20Phillips%22%5D%0A%20%20YGAP%20--%3E%20NKPC%0A%20%20I%5B%22%E5%90%8D%E4%B9%89%E6%94%BF%E7%AD%96%E5%88%A9%E7%8E%87%22%5D%20--%3E%20RI%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%22%5D%0A%20%20RI%20--%3E%20EU%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<p>需求冲击、成本推动、利率路径都进入这三方程。长期 \\(\\pi=\\pi^*\\)（目标），\\(\\tilde{y}=0\\)。短期名义刚性让 \\(i\\) 的变动改变实际利率，沿欧拉改变 \\(\\tilde{y}\\)，再反馈到 \\(\\pi\\)。</p><h3 id="粘性不是「价格永远不动」" tabindex="-1">粘性不是「价格永远不动」 <a class="header-anchor" href="#粘性不是「价格永远不动」" aria-label="Permalink to &quot;粘性不是「价格永远不动」&quot;">​</a></h3><p>粘性是调价不同步。通胀仍可很高——恶性通胀与铸币税仍可发生——只是相对价格暂时错位。超中性仍可被通胀税破坏；新凯恩斯的线性近似常把这一点藏在稳态附近。</p><p><span class="marginnote">常见误区：把「粘性」听成「价格冻结」。实际上通胀可以跑得飞快，粘住的只是相对价格——例如通胀 50% 时没改价的厂商等于实际降价约三分之一，错位的是谁贵谁便宜，不是价格水平原地不动。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>未调价厂商面对的需求由相对价格决定。央行提高 \\(i\\)，若 \\(\\mathbb{E}\\pi\\) 尚未一对一跟上，实际利率上升，欧拉要求当前需求下降，边际成本下降，能调价的厂商少涨价，\\(\\pi\\) 减速。反向亦然。预期是结构的一部分：若公众相信利率路径会把通胀拉回目标，\\(\\mathbb{E}\\pi_{t+1}\\) 立刻进入当前 \\(\\pi\\)。这与卢卡斯批判一致——规则一变，连 Phillips 的截距都变——但本课先把粘性优化写完。</p>',6)),(e(),l(p,null,{default:E(()=>[n(t,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E5%A4%AE%E8%A1%8C%E4%B8%8A%E8%B0%83%E5%90%8D%E4%B9%89%E5%88%A9%E7%8E%87%20i%22%5D%20--%3E%20Q%7B%22%E9%A2%84%E6%9C%9F%E9%80%9A%E8%83%80%E5%90%8C%E6%AD%A5%E8%B7%9F%E5%8D%87%E4%BA%86%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20R%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%20i%20%E2%88%92%20E%CF%80%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20R%20--%3E%20D%5B%22%E6%AC%A7%E6%8B%89%E7%BA%A6%E6%9D%9F%EF%BC%9A%E5%BD%93%E5%89%8D%E9%9C%80%E6%B1%82%E4%B8%8B%E9%99%8D%22%5D%0A%20%20D%20--%3E%20MC%5B%22%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E4%B8%8B%E9%99%8D%22%5D%0A%20%20MC%20--%3E%20P%5B%22%E8%83%BD%E8%B0%83%E4%BB%B7%E7%9A%84%E5%8E%82%E5%95%86%E5%B0%91%E6%B6%A8%E4%BB%B7%22%5D%0A%20%20P%20--%3E%20PI%5B%22%E9%80%9A%E8%83%80%20%CF%80%20%E5%87%8F%E9%80%9F%22%5D%0A%20%20PI%20--%3E%20F%5B%22%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%E8%A2%AB%E6%8B%89%E4%BD%8E%EF%BC%8C%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E8%BD%AE%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20F%20--%3E%20Q%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">数字实例：\\(i=5\\%\\)、\\(\\mathbb{E}\\pi=2\\%\\) 时实际利率是 \\(3\\%\\)。央行把 \\(i\\) 提到 \\(6\\%\\)：若预期通胀还停在 \\(2\\%\\)，实际利率跳到 \\(4\\%\\)，紧缩生效；若公众预期立刻跟到 \\(3\\%\\)，实际利率几乎不动，政策被中和。粘性越强，预期跟得越慢，利率越有支配力。</span></p><p>灵活价格极限 \\(\\kappa\\to\\infty\\) 或调价频率无限时，缺口被压到零，货币回到中性。RBC 走的就是这条极限，再用真实冲击解释 \\(y\\) 的波动。</p><p>三方程：动态 IS、NKPC、利率规则。自然实际利率 \\(r^n\\) 来自灵活价格均衡，增长与偏好冲击会动它。货币政策对 \\(r^n\\) 的偏离造成缺口。Calvo 的 \\(1-\\theta\\) 未调价厂商把未来边际成本贴现进今天的价格，于是 NKPC 前瞻。</p><p><span class="marginnote">NKPC 是 \\(\\pi_t=\\beta\\mathbb{E}_t\\pi_{t+1}+\\lambda\\tilde{y}_t\\) 一类。混合 NKPC 加滞后项是经验修补。本课先前瞻基准。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不校准 \\(\\kappa\\)，不把金融摩擦、有效下限写进方程——ZLB 是后课。工资粘性、不完全信息可以并列，不是否定 Calvo。量化栏的限价是微观；这里的粘性是宏观名义刚性和垄断竞争加成。菜单成本是替代微观，不是把 Calvo 日历当真。</p><p>后课默认：短期宏观用欧拉 + 前瞻 Phillips + 利率工具。下一课把同一套波动对照真实经济周期：若价格灵活，还剩什么周期。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧拉要能被名义利率推动，必须有名义刚性。</li><li>新凯恩斯 Phillips 来自交错调价，通胀前瞻。</li><li>工具是利率路径； \\(M\\) 由需求内生。</li><li>长期中性、自然产出可被真实冲击移动。</li><li>灵活价格极限回到 RBC 的骨架。</li><li>出处：Woodford, <em>Interest and Prices</em>；Calvo 交错定价传统。</li></ul>',9))])}const b=r(d,[["render",A]]);export{P as __pageData,b as default};
